            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "La guerra es la obra de arte de los militares, la coronación de su formación, el broche dorado de su profesión. No han sido creados para brillar en la paz.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "La muerte no existe. La gente solo se muere cuando la olvidan. Si puedes recordarme, siempre estaré contigo.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Nadie sabe para quién escribe. Cada libro es un mensaje lanzado en una botella al mar con la esperanza de que arribe a otra orilla.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Era una de esas mujeres estoicas y prácticas de nuestro país, que con cada hombre que pasa por sus vidas tienen un hijo y además recogen en su hogar a los niños que otros abandonan, a los parientes más pobres y a cualquiera que necesite una madre, una hermana, una tía, mujeres que son el pillar central de muchas vidas ajenas, que crían hijos para que se vayan también y que ven partir a sus hombres sin un reproche, porque tienen otras urgencias mayoresde las cuales ocuparse.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Me pareció igual a tantas otras que conocí en los comedores populares, en el hospital de mi tío Jaime, en la Vicaría donde iban a buscar a sus muertos. Le dije que habÍa corrido mucho riesgo al ayudarme y ella sonrió. Entonces supe que el coronel García y otros como él tienen sus días contados, porque no han podido destruir el espíritu de esas mujeres.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Después el nieto de la mujer violada repite el gesto con la nieta del violador y dentro de cuarenta años, tal vez, mi nieto tumbe entre las matas del río a la suya y así, por los siglos venideros, en una historia inacabable de dolor, de sangre y de amor.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Escribo, ella escribió, que la memoria es frágil y el transcurso de una vida es muy breve y sucede de todo tan de prisa, que no alcanzamos a ver la la relación entre los acontecimientos, no podemos medir la consequencia de los actos, creemos en la ficción del tiempo, en el presente, el pasado y el futuro, pero puede ser también que todo ocurre simultáneamente, como decían las tres hermanas Mora, que eran capaces de ver en el espacio los espíritus de todas las épocas.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Quiero pensar que mi oficio es la vida y que mi misión no es prolongar el odio, sino sólo llenar estas páginas mientras espero el regreso de Miguel, mientras entierro a mi abuelo que ahora descansa a mi lado en este cuarto, mientras aguardo que lleguen tiempos mejores, gestando a la criatura que tengo en el vientre, hija de tantas volaciones, o tal vez hija de Miguel, pero sobre todo hija mía.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Tenía el nombre de Belisa Crepusculario, pero no por fe de bautismo o acierto de su madre, sino porque ella misma lo buscó hasta encontrarlo y se vistió con él.", Author = "Isabel Allende" },
            new Quote { Id = "https://es.wikiquote.org/wiki/Isabel_Allende", Text = "Esa noche murió Clarisa sin angustia. De cáncer, diagnosticó el médico al ver sus capullos de alas; de santidad, proclamaron los devotos apiñados en la calle con cirios y flores; de asombro, digo yo, porque estuve con ella cuando nos visitó el Papa.", Author = "Isabel Allende" },
